def _load_phase(pair_dir: Path, method: str) -> Optional[np.ndarray]:
    """Load wrapped phase (H, W) for the given method."""
    import rasterio
    fname = "ifg_goldstein.tif" if method == "goldstein" else "ifg_film_unet.tif"
    path = pair_dir / fname
    if not path.exists():
        return None
    try:
        with rasterio.open(path) as src:
            re = src.read(1).astype(np.float32)
            im = src.read(2).astype(np.float32)
        return np.arctan2(im, re)
    except Exception as e:
        log.warning("Could not load %s: %s", path, e)
        return None


def _load_coherence(pair_dir: Path) -> Optional[np.ndarray]:
    import rasterio
    try:
        with rasterio.open(pair_dir / "coherence.tif") as src:
            return src.read(1).astype(np.float32)
    except Exception:
        return None


def _load_unw(pair_dir: Path) -> Optional[np.ndarray]:
    import rasterio
    path = pair_dir / "unw_phase.tif"
    if not path.exists():
        return None  # avoid GDAL file-not-found noise
    try:
        with rasterio.open(path) as src:
            return src.read(1).astype(np.float32)
    except Exception:
        return None


